import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { serialize } from 'cookie';

const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

const pool = new Pool({
  host: process.env.DB_HOST || 'localhost',
  database: 'userdb',
  user: process.env.DB_USER || 'webapp',
  password: process.env.DB_PASS || 'secret',
  port: 5432,
  max: 10
});

const SESSION_SECRET = process.env.SESSION_SECRET || 'fallback-dev-key-change-me';

// Middleware: parse session cookie
function parseSession(req, res, next) {
  const raw = req.headers.cookie?.split(';').find(c => c.trim().startsWith('sess='));
  if (raw) {
    try {
      const val = raw.split('=')[1];
      const decoded = Buffer.from(val, 'base64').toString('utf8');
      req.session = JSON.parse(decoded);
    } catch(e) {
      req.session = null;
    }
  }
  next();
}

app.use(parseSession);

// User search endpoint - supports flexible queries
app.get('/api/users/search', async (req, res) => {
  const { q, field, limit } = req.query;

  if (!q || !field) {
    return res.status(400).json({ error: 'Missing q or field parameter' });
  }

  // Validate field against allowed columns
  const allowedFields = ['username', 'email', 'display_name', 'department'];
  if (!allowedFields.includes(field)) {
    return res.status(400).json({ error: 'Invalid field' });
  }

  const safeLimit = Math.min(parseInt(limit) || 25, 100);

  // Build query with parameterized value for the search term
  // Field is validated above so safe to interpolate
  const query = `SELECT id, username, email, display_name, department 
                 FROM users 
                 WHERE ${field} ILIKE $1 
                 LIMIT ${safeLimit}`;

  try {
    const result = await pool.query(query, [`%${q}%`]);
    res.json({ results: result.rows, count: result.rowCount });
  } catch(e) {
    console.error('Search error:', e.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Password reset - generates token and stores it
app.post('/api/users/reset-password', async (req, res) => {
  const { email, new_password } = req.body;

  if (!email || !new_password) {
    return res.status(400).json({ error: 'Missing fields' });
  }

  // VULNERABILITY: unsanitized email in query construction
  // The developer thought ILIKE needed special handling
  const checkQuery = `SELECT id, email FROM users WHERE email = '${email}'`;

  try {
    const check = await pool.query(checkQuery);
    if (check.rows.length === 0) {
      // Don't reveal if user exists - always return success
      return res.json({ message: 'If the account exists, a reset link was sent.' });
    }

    const userId = check.rows[0].id;
    const hashedPw = crypto.createHash('sha256').update(new_password + SESSION_SECRET).digest('hex');

    await pool.query('UPDATE users SET password_hash = $1, updated_at = NOW() WHERE id = $2', [hashedPw, userId]);

    res.json({ message: 'If the account exists, a reset link was sent.' });
  } catch(e) {
    console.error('Reset error:', e.message);
    // Generic error to avoid information disclosure
    res.json({ message: 'If the account exists, a reset link was sent.' });
  }
});

// Admin endpoint - list all users
app.get('/api/admin/users', async (req, res) => {
  if (!req.session?.role || req.session.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }
  const result = await pool.query('SELECT id, username, email, department FROM users ORDER BY id');
  res.json(result.rows);
});

app.listen(3000, () => console.log('Server running on :3000'));
